 * A hand written recursive/iterative scanner for the small language
 * described in the task. `scan(source)` returns an array of tokens or
 * throws a `ScanError` carrying the line, column and reason of the first
 * problem encountered.
 */

export class ScanError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

const isLetter = (ch) => ch !== undefined && /\p{L}/u.test(ch)
const isDecDigit = (ch) => ch !== undefined && /[0-9]/.test(ch)
const isHexDigit = (ch) => ch !== undefined && /[0-9a-fA-F]/.test(ch)
const isBinDigit = (ch) => ch !== undefined && /[01]/.test(ch)
const isOctDigit = (ch) => ch !== undefined && /[0-7]/.test(ch)
const isTrailing = (ch) => ch !== undefined && /[\p{L}\p{N}_]/u.test(ch)

class Cursor {
  constructor(source) {
    this.chars = Array.from(source)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof() {
    return this.i >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const ch = this.chars[this.i++]
    if (ch === '\n') {
      this.line++
      this.col = 1
    } else if (ch === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return ch
  }
}

function scanRun(cur, isDigitFn) {
  let s = ''
  while (!cur.eof()) {
    if (isDigitFn(cur.peek())) {
      s += cur.advance()
    } else if (cur.peek() === '_' && isDigitFn(cur.peek(1))) {
      s += cur.advance()
      s += cur.advance()
    } else {
      break
    }
  }
  return s
}

function scanNumber(cur) {
  const startPos = cur.pos()
  let text = cur.advance() // first digit
  let valid = true

  if (text === '0' && (cur.peek() === 'x' || cur.peek() === 'X' || cur.peek() === 'b' || cur.peek() === 'B' || cur.peek() === 'o' || cur.peek() === 'O')) {
    const prefixChar = cur.peek()
    text += cur.advance()
    let isDigitFn
    if (prefixChar === 'x' || prefixChar === 'X') isDigitFn = isHexDigit
    else if (prefixChar === 'b' || prefixChar === 'B') isDigitFn = isBinDigit
    else isDigitFn = isOctDigit

    if (isDigitFn(cur.peek())) {
      text += scanRun(cur, isDigitFn)
      valid = true
    } else {
      valid = false
    }
  } else {
    text += scanRun(cur, isDecDigit)

    if (cur.peek() === '.' && isDecDigit(cur.peek(1))) {
      text += cur.advance() // '.'
      text += cur.advance() // first fraction digit
      text += scanRun(cur, isDecDigit)
    }

    if (cur.peek() === 'e' || cur.peek() === 'E') {
      const la1 = cur.peek(1)
      const la2 = cur.peek(2)
      if (isDecDigit(la1)) {
        text += cur.advance() // e
        text += cur.advance() // first exponent digit
        text += scanRun(cur, isDecDigit)
      } else if ((la1 === '+' || la1 === '-') && isDecDigit(la2)) {
        text += cur.advance() // e
        text += cur.advance() // sign
        text += cur.advance() // first exponent digit
        text += scanRun(cur, isDecDigit)
      }
    }
  }

  let trailing = ''
  while (isTrailing(cur.peek())) {
    trailing += cur.advance()
  }

  if (!valid || trailing.length > 0) {
    throw new ScanError(startPos.line, startPos.col, `invalid number ${text}${trailing}`)
  }

  return { kind: 'number', line: startPos.line, col: startPos.col, text }
}

function scanIdent(cur) {
  const startPos = cur.pos()
  let text = cur.advance()
  while (isLetter(cur.peek()) || isDecDigit(cur.peek()) || cur.peek() === '_') {
    text += cur.advance()
  }
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, line: startPos.line, col: startPos.col, text }
}

function scanString(cur) {
  const startPos = cur.pos()
  cur.advance() // opening quote
  let decoded = ''
  for (;;) {
    if (cur.eof()) throw new ScanError(startPos.line, startPos.col, 'unterminated string')
    const ch = cur.peek()
    if (ch === '"') {
      cur.advance()
      break
    }
    if (ch === '\n') {
      const p = cur.pos()
      throw new ScanError(p.line, p.col, 'newline in string')
    }
    if (ch === '\\') {
      const bsPos = cur.pos()
      cur.advance() // backslash
      if (cur.eof()) throw new ScanError(startPos.line, startPos.col, 'unterminated string')
      const esc = cur.peek()
      switch (esc) {
        case 'n':
          cur.advance()
          decoded += '\n'
          break
        case 't':
          cur.advance()
          decoded += '\t'
          break
        case 'r':
          cur.advance()
          decoded += '\r'
          break
        case '\\':
          cur.advance()
          decoded += '\\'
          break
        case '"':
          cur.advance()
          decoded += '"'
          break
        case '0':
          cur.advance()
          decoded += '\0'
          break
        case 'x': {
          cur.advance() // x
          let h = ''
          let ok = true
          for (let k = 0; k < 2; k++) {
            if (cur.eof() || !isHexDigit(cur.peek())) {
              ok = false
              break
            }
            h += cur.advance()
          }
          if (!ok) throw new ScanError(bsPos.line, bsPos.col, `invalid escape \\x`)
          decoded += String.fromCharCode(parseInt(h, 16))
          break
        }
        case 'u': {
          cur.advance() // u
          if (cur.peek() !== '{') throw new ScanError(bsPos.line, bsPos.col, `invalid escape \\u`)
          cur.advance() // {
          let hex = ''
          while (!cur.eof() && isHexDigit(cur.peek())) hex += cur.advance()
          if (hex.length === 0) throw new ScanError(bsPos.line, bsPos.col, `invalid escape \\u`)
          if (cur.eof() || cur.peek() !== '}') throw new ScanError(bsPos.line, bsPos.col, `invalid escape \\u`)
          cur.advance() // }
          const cp = parseInt(hex, 16)
          if (cp > 0x10ffff) throw new ScanError(bsPos.line, bsPos.col, `invalid escape \\u`)
          decoded += String.fromCodePoint(cp)
          break
        }
        default:
          throw new ScanError(bsPos.line, bsPos.col, `invalid escape \\${esc}`)
      }
    } else {
      decoded += cur.advance()
    }
  }
  return { kind: 'string', line: startPos.line, col: startPos.col, value: decoded }
}

function scanRawString(cur) {
  const startPos = cur.pos()
  cur.advance() // r
  cur.advance() // opening quote
  let decoded = ''
  for (;;) {
    if (cur.eof()) throw new ScanError(startPos.line, startPos.col, 'unterminated string')
    const ch = cur.peek()
    if (ch === '"') {
      cur.advance()
      break
    }
    decoded += cur.advance()
  }
  return { kind: 'rawstring', line: startPos.line, col: startPos.col, value: decoded }
}

function skipWhitespaceAndComments(cur) {
  for (;;) {
    const ch = cur.peek()
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      cur.advance()
      continue
    }
    if (ch === '/' && cur.peek(1) === '/') {
      cur.advance()
      cur.advance()
      while (!cur.eof() && cur.peek() !== '\n') cur.advance()
      continue
    }
    if (ch === '/' && cur.peek(1) === '*') {
      const startPos = cur.pos()
      cur.advance()
      cur.advance()
      let depth = 1
      while (depth > 0) {
        if (cur.eof()) throw new ScanError(startPos.line, startPos.col, 'unterminated block comment')
        if (cur.peek() === '/' && cur.peek(1) === '*') {
          cur.advance()
          cur.advance()
          depth++
        } else if (cur.peek() === '*' && cur.peek(1) === '/') {
          cur.advance()
          cur.advance()
          depth--
        } else {
          cur.advance()
        }
      }
      continue
    }
    break
  }
}

function scanPunct(cur) {
  const startPos = cur.pos()
  const two = (cur.peek() ?? '') + (cur.peek(1) ?? '')
  if (PUNCT2.includes(two)) {
    cur.advance()
    cur.advance()
    return { kind: 'punct', line: startPos.line, col: startPos.col, text: two }
  }
  const one = cur.peek()
  if (PUNCT1.includes(one)) {
    cur.advance()
    return { kind: 'punct', line: startPos.line, col: startPos.col, text: one }
  }
  throw new ScanError(startPos.line, startPos.col, `unexpected character ${one}`)
}

export function scan(source) {
  const cur = new Cursor(source)
  const tokens = []

  for (;;) {
    skipWhitespaceAndComments(cur)
    if (cur.eof()) break

    const ch = cur.peek()
    if (ch === 'r' && cur.peek(1) === '"') {
      tokens.push(scanRawString(cur))
    } else if (isLetter(ch) || ch === '_') {
      tokens.push(scanIdent(cur))
    } else if (isDecDigit(ch)) {
      tokens.push(scanNumber(cur))
    } else if (ch === '"') {
      tokens.push(scanString(cur))
    } else {
      tokens.push(scanPunct(cur))
    }
  }

  return tokens
}
