  if (token.kind === 'string' || token.kind === 'rawstring') {
    return JSON.stringify(token.value)
  }
  return token.text
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = scan(source)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  if (mode === 'tokens') {
    let out = ''
    for (const token of tokens) {
      out += `${token.line}:${token.col} ${token.kind} ${tokenBody(token)}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const token of tokens) {
      counts[token.kind]++
    }
    let out = ''
    for (const kind of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      out += `${kind} ${counts[kind]}\n`
    }
